/* ===== V26.64 · RECURSOS HUMANOS con Plan Micro (0–10 legajos activos) y Plan Completo (11 o más) =====
   · El plan NO se configura a mano: lo decide la cantidad de legajos ACTIVOS. El único disparador es el cambio de estado
     de un legajo (alta, baja, reactivación). Cada transición queda registrada (S.hrPlanLog + auditoría RRHH_PLAN) para facturar.
   · Middleware de autorización: hrHas(f) / hrNeed(f). Las funciones del Plan Completo se bloquean en la acción, no sólo en la pantalla.
   · Fichaje omnicanal: PIN (modo kiosco), QR estático o dinámico (lector USB o cámara), NFC (Web NFC, Chrome Android),
     ubicación (geocerca) para el fichaje desde el celular. Reconocimiento facial y huella: adaptador preparado, PENDIENTE de
     dispositivo y de revisión legal (datos biométricos): no se simulan. Wi-Fi local: el navegador no puede leer la red (se declara).
   · Nómina: liquidación INTERNA con parámetros configurables (horas extra, tardanzas, ausencias, comisiones, deducciones).
     No reemplaza el recibo de haberes legal ni inventa alícuotas: todo [VERIFICAR] con el contador.
   · Los archivos (documentos, CV, firmas) quedan en ESTE equipo y en el respaldo; en la nube viaja sólo su descripción. */
const HR_FULL={portal:'Portal del empleado',approvals:'Aprobaciones en varios niveles',payroll:'Nómina avanzada',docsAdv:'Gestión documental avanzada',ats:'Reclutamiento',vacations:'Control de vacaciones'};
const HR_LIMIT=10;
const HR_REQ_T={vacaciones:'Vacaciones',licencia:'Licencia',enfermedad:'Enfermedad',justificante:'Justificante',otro:'Otro'};
const HR_REQ_L={vacaciones:'V',licencia:'L',enfermedad:'E',justificante:'J',otro:'O'};
const HR_STAGES=[['recibido','CV recibido'],['entrevista','Entrevista'],['prueba','Prueba'],['oferta','Oferta'],['contratado','Contratado'],['descartado','Descartado']];
const HR_DOC_T={dni:'DNI',contrato:'Contrato',alta:'Alta temprana',certificado:'Certificado',cv:'CV',otro:'Otro'};
const HR_FLOW_T={supervisor:'Supervisor',rrhh:'RR. HH.',admin:'Administración'};
function hrCfg(){const c=S.cfg.hr=S.cfg.hr||{};if(c.on===undefined)c.on=false;c.methods=Object.assign({pin:true,qr:true,nfc:false,face:false,finger:false,geo:false},c.methods||{});
 c.geo=Object.assign({lat:'',lon:'',r:150},c.geo||{});if(c.tol===undefined)c.tol=10;if(c.otDaily===undefined)c.otDaily=8;if(c.otFactor===undefined)c.otFactor=1.5;if(c.otSun===undefined)c.otSun=2;
 if(c.monthHours===undefined)c.monthHours=200;if(c.lateDisc===undefined)c.lateDisc=false;if(c.absDisc===undefined)c.absDisc=false;if(!Array.isArray(c.deds))c.deds=[];
 if(!Array.isArray(c.flow)||!c.flow.length)c.flow=['supervisor','rrhh','admin'];if(!Array.isArray(c.vacTable)||!c.vacTable.length)c.vacTable=[[0,14],[5,21],[10,28],[20,35]];
 c.acct=Object.assign({name:'',mail:'',wa:''},c.acct||{});return c;}
function hrInit(){for(const k of['hrShifts','hrReqs','hrDocs','hrPays','hrJobs','hrCands','hrItems','hrMsgs','hrPlanLog'])if(!Array.isArray(S[k]))S[k]=[];if(!S.hrFiles||typeof S.hrFiles!=='object')S.hrFiles={};hrCfg();}
const hrOn=()=>{try{return !!hrCfg().on;}catch(e){return false;}};
const hrActive=()=>S.employees.filter(e=>e.active).length;
const hrTier=()=>hrActive()>HR_LIMIT?'full':'micro';
const HR_PLAN_N={micro:'Plan Micro',full:'Plan Completo'};
function hrHas(f){return !HR_FULL[f]||hrTier()==='full';}
function hrNeed(f){if(hrHas(f))return true;toast((HR_FULL[f]||'Esta función')+': disponible en el Plan Completo (más de '+HR_LIMIT+' legajos activos). Hoy hay '+hrActive()+'.',1);return false;}
/* transición automática: se llama cuando cambia el estado de un legajo; también se revisa al abrir RR. HH. por si llegó un cambio de otro equipo */
function hrPlanSync(reason){hrInit();const c=hrCfg();const t=hrTier();if(!c.plan){c.plan=t;return;}if(c.plan===t)return;
 const ev={id:uid(),ts:now(),from:c.plan,to:t,active:hrActive(),by:user?user.name:'sistema',reason:String(reason||'cambio de estado de legajos').slice(0,80)};S.hrPlanLog.push(ev);c.plan=t;
 audit('RRHH_PLAN',HR_PLAN_N[ev.from]+' → '+HR_PLAN_N[t]+' · '+ev.active+' legajos activos · '+ev.reason);save();}
const hrEmp=id=>S.employees.find(e=>e.id===id)||null;
const hrDept=e=>(e&&e.dept)||((S.puestos.find(p=>p.id===(e&&e.puestoId))||{}).name)||'Sin área';
const hrHourly=e=>e?(e.payMode==='mes'?Math.round((e.salary||0)/Math.max(1,hrCfg().monthHours)):(e.rate||0)):0;
const hrMin=s=>{const m=/^(\d{1,2}):(\d{2})$/.exec(String(s||''));return m?(+m[1])*60+(+m[2]):NaN;};
const hrTs=(day,hhmm)=>new Date(day+'T'+hhmm+':00').getTime();
const hrShift=(empId,day)=>S.hrShifts.find(s=>s.empId===empId&&s.day===day)||null;
const hrLeave=(empId,day)=>S.hrReqs.find(r=>r.empId===empId&&r.state==='aprobada'&&r.from<=day&&r.to>=day)||null;
function hrDays(from,to){const o=[];let k=from,g=0;while(k<=to&&g++<400){o.push(k);k=addDays(k,1);}return o;}
function hrDay(e,day){const c=hrCfg();const h=hoursOn(e.id,day);const sh=hrShift(e.id,day);const lv=hrLeave(e.id,day);
 const ps=S.punches.filter(p=>p.empId===e.id&&dkey(p.ts)===day&&p.kind==='in').sort((a,b)=>a.ts-b.ts);let late=0;
 if(sh&&ps.length){const st=hrTs(day,sh.from);const d=Math.round((ps[0].ts-st)/60000);if(d>c.tol)late=d;}
 const shH=sh?Math.max(0,(hrMin(sh.to)-hrMin(sh.from))/60):0;
 const past=hrTs(day,sh?sh.from:'00:00')+c.tol*60000<now();
 const absent=!!(sh&&!lv&&h.h===0&&past);const ot=Math.max(0,h.h-c.otDaily);
 return {h:h.h,flag:h.flag,sh,shH,lv,late,absent,ot,sun:dowOfKey(day)===0};}
function hrStats(e,from,to){const o={days:0,h:0,ot:0,otSun:0,late:0,lateN:0,abs:0,absH:0,flags:0,lv:{},sched:0};
 for(const d of hrDays(from,to)){const x=hrDay(e,d);if(x.h>0)o.days++;o.h+=x.h;if(x.sun)o.otSun+=x.ot;else o.ot+=x.ot;if(x.late){o.late+=x.late;o.lateN++;}if(x.absent){o.abs++;o.absH+=x.shH;}if(x.flag)o.flags++;if(x.lv)o.lv[x.lv.type]=(o.lv[x.lv.type]||0)+1;if(x.sh&&!x.lv)o.sched++;}
 return o;}
/* ---------- nómina (liquidación interna) ---------- */
function hrComm(e,from,to){if(!e.userName||!(e.commPct>0))return 0;const a=new Date(from+'T00:00:00').getTime(),b=new Date(to+'T23:59:59').getTime();
 const tot=S.sales.filter(s=>s.status==='ok'&&s.user===e.userName&&s.ts>=a&&s.ts<=b).reduce((x,s)=>x+s.total,0);return Math.round(tot*e.commPct/100);}
function hrPayLine(e,period){const c=hrCfg();const from=period+'-01';const to=addDays(addDays(from,32).slice(0,7)+'-01',-1);const st=hrStats(e,from,to);const hv=hrHourly(e);
 const base=e.payMode==='mes'?(e.salary||0):Math.round(st.h*(e.rate||0));
 const otAmt=Math.round(st.ot*hv*(c.otFactor-(e.payMode==='mes'?0:1))+st.otSun*hv*(c.otSun-(e.payMode==='mes'?0:1)));
 const lateAmt=c.lateDisc?Math.round(st.late/60*hv):0;const absAmt=c.absDisc&&e.payMode==='mes'?Math.round(st.absH*hv):0;const comm=hrComm(e,from,to);
 const gross=Math.max(0,base+otAmt-lateAmt-absAmt+comm);const deds=c.deds.map(d=>({n:d.n,a:Math.round(gross*(+d.pct||0)/100)}));const net=gross-deds.reduce((x,d)=>x+d.a,0);
 return {empId:e.id,name:e.name,dept:hrDept(e),cbu:e.cbu||'',mode:e.payMode==='mes'?'mensual':'por hora',hours:Math.round(st.h*100)/100,ot:Math.round((st.ot+st.otSun)*100)/100,late:st.late,abs:st.abs,base,otAmt,lateAmt,absAmt,comm,gross,deds,net};}
function hrPayCalc(period){return S.employees.filter(e=>e.active||S.punches.some(p=>p.empId===e.id&&dkey(p.ts).slice(0,7)===period)).map(e=>hrPayLine(e,period));}
/* ---------- vacaciones ---------- */
function hrVacEntitled(e,year){const c=hrCfg();if(!e.hire)return (e.vacExtra||0);const yrs=Math.max(0,year-(+e.hire.slice(0,4))-((e.hire.slice(5)>'12-31')?1:0));let d=0;for(const [y,n] of c.vacTable)if(yrs>=y)d=n;return d+(+e.vacExtra||0);}
function hrVacTaken(e,year,pend){return S.hrReqs.filter(r=>r.empId===e.id&&r.type==='vacaciones'&&(pend?r.state==='pendiente':r.state==='aprobada')).reduce((x,r)=>x+hrDays(r.from<year+'-01-01'?year+'-01-01':r.from,r.to>year+'-12-31'?year+'-12-31':r.to).filter(d=>d.slice(0,4)===String(year)).length,0);}
/* ---------- alertas ---------- */
function hrAlerts(){hrInit();const out=[];const t=dkey(now());const lim=addDays(t,30);const full=hrTier()==='full';
 S.employees.filter(e=>e.active).forEach(e=>{if(e.cEnd&&e.cEnd<=lim)out.push({c:e.cEnd<t?'red':'amber',k:'contrato',t:'Contrato de '+e.name+(e.cEnd<t?' vencido el ':' termina el ')+dmy(e.cEnd),go:'legajos'});
  const x=hrDay(e,t);if(x.absent)out.push({c:'red',k:'asistencia',t:e.name+': tenía turno a las '+x.sh.from+' y no fichó',go:'calendario'});else if(x.late)out.push({c:'amber',k:'asistencia',t:e.name+': llegó '+x.late+' min tarde hoy',go:'calendario'});
  for(const d of hrDays(addDays(t,-7),addDays(t,-1)))if(hoursOn(e.id,d).flag)out.push({c:'amber',k:'asistencia',t:e.name+': fichada incompleta el '+dmy(d),go:'reportes'});});
 if(full)S.hrDocs.filter(d=>d.exp&&d.exp<=lim&&!d.del).forEach(d=>out.push({c:d.exp<t?'red':'amber',k:'documento',t:(HR_DOC_T[d.kind]||'Documento')+' de '+(hrEmp(d.empId)||{name:'—'}).name+(d.exp<t?' vencido el ':' vence el ')+dmy(d.exp),go:'documentos'}));
 const pend=S.hrReqs.filter(r=>r.state==='pendiente').length;if(pend)out.push({c:'amber',k:'solicitudes',t:pend+' solicitud(es) del personal esperando aprobación',go:'solicitudes'});
 const pl=S.hrPlanLog[S.hrPlanLog.length-1];if(pl&&now()-pl.ts<7*864e5)out.push({c:'amber',k:'plan',t:'Cambio de plan: '+HR_PLAN_N[pl.from]+' → '+HR_PLAN_N[pl.to]+' ('+dmy(dkey(pl.ts))+')',go:'inicio'});
 return out;}
/* ---------- QR y fichaje omnicanal ---------- */
function hrKey(){const a=new Uint8Array(12);crypto.getRandomValues(a);return [...a].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function hrOtp(k,win){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('VBHR|'+k+'|'+win));const v=new DataView(d);return String(v.getUint32(0)%1000000).padStart(6,'0');}
const hrWin=()=>Math.floor(now()/30000);
const hrUsed=new Set();
async function hrParseCred(raw){const s=String(raw||'').trim();let m=/^VBHR1\|([A-Za-z0-9_-]{1,40})\|([0-9a-f]{24})$/.exec(s);
 if(m){const e=hrEmp(m[1]);if(!e||!e.active||!e.qk||e.qk!==m[2])return{err:'Credencial inválida o dada de baja.'};return{e,method:'qr'};}
 m=/^VBHR2\|([A-Za-z0-9_-]{1,40})\|(\d{6})$/.exec(s);
 if(m){const e=hrEmp(m[1]);if(!e||!e.active||!e.qk)return{err:'Código inválido.'};const w=hrWin();const ok=(await hrOtp(e.qk,w))===m[2]||(await hrOtp(e.qk,w-1))===m[2];
  if(!ok)return{err:'El código QR venció: generá uno nuevo.'};const key=e.id+'|'+m[2];if(hrUsed.has(key))return{err:'Ese código ya se usó.'};hrUsed.add(key);return{e,method:'qr dinámico'};}
 m=/^VBHRN\|([A-Za-z0-9_-]{1,40})\|([0-9a-f]{24})$/.exec(s);if(m){const e=hrEmp(m[1]);if(!e||!e.active||e.qk!==m[2])return{err:'Tarjeta NFC inválida.'};return{e,method:'nfc'};}
 return{err:'No es una credencial de fichaje.'};}
function hrPunch(e,method,extra){const last=lastPunch(e.id);if(last&&now()-last.ts<60000)return{err:'Fichada repetida: esperá 60 segundos.'};
 const r=punch(e.id,e.pin,method,{});if(r.p&&extra)Object.assign(r.p,extra);if(r.p)save();return r;}
function hrDist(a,b,c,d){const R=6371000,t=x=>x*Math.PI/180;const dl=t(c-a),dn=t(d-b);const h=Math.sin(dl/2)**2+Math.cos(t(a))*Math.cos(t(c))*Math.sin(dn/2)**2;return Math.round(2*R*Math.asin(Math.sqrt(h)));}
/* ---------- archivos locales (documentos, CV, firmas) ---------- */
const HR_FILE_MAX=1500000;
function hrPickFile(inp){return new Promise((res,rej)=>{const f=inp&&inp.files&&inp.files[0];if(!f)return res(null);if(f.size>HR_FILE_MAX)return rej(new Error('El archivo supera 1,5 MB.'));
 if(!/^(image\/(png|jpeg|webp)|application\/pdf)$/.test(f.type))return rej(new Error('Sólo PDF, JPG, PNG o WEBP.'));const rd=new FileReader();rd.onload=()=>res({name:f.name.slice(0,80),size:f.size,type:f.type,data:rd.result});rd.onerror=()=>rej(new Error('No se pudo leer el archivo.'));rd.readAsDataURL(f);});}
function hrFileOpen(id){const d=S.hrFiles[id];if(!d)return toast('El archivo está guardado en otro equipo (en la nube sólo viaja su descripción).',1);const doc=S.hrDocs.find(x=>x.id===id)||S.hrCands.find(x=>x.cvId===id)||{};const a=document.createElement('a');a.href=d;a.download=(doc.name||doc.cvName||'archivo').replace(/[^\w.\- ]/g,'_');document.body.appendChild(a);a.click();a.remove();}
A.hrFile=el=>hrFileOpen(el.dataset.id);

/* ===================== PANTALLA «Recursos Humanos» ===================== */
let hrTab='inicio',hrCal='',hrRep={from:'',to:''},hrPer='',hrJob='',hrDash=30,hrQ='';
const HR_TABS=[['inicio','Plan y resumen'],['legajos','Legajos'],['calendario','Turnos y licencias'],['fichaje','Fichaje'],['reportes','Reporte para el contador'],
 ['solicitudes','Solicitudes','approvals'],['vacaciones','Vacaciones','vacations'],['nomina','Nómina','payroll'],['documentos','Documentos y entregas','docsAdv'],['reclutamiento','Reclutamiento','ats'],
 ['tablero','Tablero','dash'],['alertas','Alertas'],['avisos','Avisos al personal'],['ajustes','Ajustes','cfg']];
function hrTabOk(t){const x=HR_TABS.find(y=>y[0]===t);if(!x)return false;if(x[2]==='dash')return can('hr_dash');if(x[2]==='cfg')return isAdm();return true;}
function hrLock(f){return `<div class="card hr-lock"><h3>🔒 ${esc(HR_FULL[f])}</h3><p>Es parte del <b>Plan Completo</b>, que se activa solo cuando el comercio tiene <b>más de ${HR_LIMIT} legajos activos</b> (hoy: ${hrActive()}).</p><p class="sm mut">En el Plan Micro la pantalla se mantiene liviana: fichaje en terminal compartida, legajo esencial, calendario y reporte para el contador.</p></div>`;}
function hrEmpOpts(sel,all){return (all?'<option value="">Todos</option>':'')+S.employees.filter(e=>e.active).map(e=>`<option value="${e.id}" ${sel===e.id?'selected':''}>${esc(e.name)}</option>`).join('');}
function hrKpi(l,v,sub){return `<div class="card ux-k"><span>${esc(l)}</span><b>${v}</b>${sub?`<small>${sub}</small>`:''}</div>`;}
function hrInicio(){const t=hrTier(),n=hrActive();const al=hrAlerts();const log=S.hrPlanLog.slice(-6).reverse();
 return `<div class="hr-plan ${t}"><div><span class="sm">Plan vigente</span><b>${HR_PLAN_N[t]}</b><span class="sm">${n} legajo(s) activo(s) · ${t==='micro'?'hasta '+HR_LIMIT+' es Micro':'más de '+HR_LIMIT+' es Completo'}</span></div>
  <div class="hr-meter" role="img" aria-label="${n} de ${HR_LIMIT} legajos del Plan Micro"><i style="width:${Math.min(100,n/HR_LIMIT*100)}%"></i></div>
  <p class="sm" style="margin:.4rem 0 0">El plan cambia <b>solo</b> cuando un legajo pasa a activo o inactivo; no hay que configurarlo. Cada cambio queda registrado para la facturación.</p></div>
 <div class="grid g4" style="margin-top:1rem">${hrKpi('Legajos activos',n)}${hrKpi('Fichando hoy',S.employees.filter(e=>e.active&&hoursOn(e.id,dkey(now())).h>0||(lastPunch(e.id)&&dkey(lastPunch(e.id).ts)===dkey(now()))).length)}${hrKpi('Alertas',al.length)}${hrKpi('Solicitudes pendientes',S.hrReqs.filter(r=>r.state==='pendiente').length)}</div>
 <div class="grid g2" style="margin-top:1rem"><div class="card"><h3>Qué incluye cada plan</h3><div class="tw"><table><thead><tr><th>Función</th><th>Micro</th><th>Completo</th></tr></thead><tbody>
 ${[['Fichaje en terminal compartida (PIN / QR / NFC)',1,1],['Legajo esencial y documentación digitalizada',1,1],['Calendario de turnos y licencias',1,1],['Reporte de horas y ausencias para el contador',1,1],['Tablero, alertas y avisos al personal',1,1]].concat(Object.values(HR_FULL).map(x=>[x,0,1])).map(r=>`<tr><td>${esc(r[0])}</td><td>${r[1]?'✓':'—'}</td><td>✓</td></tr>`).join('')}</tbody></table></div></div>
 <div class="card"><h3>Historial de plan</h3>${log.length?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Cambio</th><th class="r">Activos</th></tr></thead><tbody>${log.map(l=>`<tr><td>${fmtDT(l.ts)}</td><td>${HR_PLAN_N[l.from]} → <b>${HR_PLAN_N[l.to]}</b><br><span class="sm mut">${esc(l.reason)} · ${esc(l.by)}</span></td><td class="r">${l.active}</td></tr>`).join('')}</tbody></table></div>`:'<p class="mut">Sin cambios de plan todavía.</p>'}
 ${IS_CLIENT?'':`<p class="sm mut" style="margin-top:.6rem">Demo: probá el cambio automático de plan sumando o dando de baja personal de ejemplo.</p><div class="row"><button class="btn sm" data-act="hrDemoMore">+ Personal de ejemplo</button><button class="btn sm" data-act="hrDemoLess">Dar de baja el de ejemplo</button></div>`}</div></div>`;}
function hrLegajos(){const q=norm(hrQ);const L=S.employees.filter(e=>!q||norm(e.name+' '+hrDept(e)+' '+(e.phone||'')).includes(q));
 return `<div class="card"><div class="row"><h3 class="sp">Legajos (${L.length})</h3><input id="hr-q" placeholder="Buscar por nombre o área" value="${esc(hrQ)}" style="max-width:260px">${can('staff')?'<button class="btn gold sm" data-act="hrEmp" data-id="">+ Legajo</button>':''}</div>
 <div class="tw"><table><thead><tr><th>Nombre</th><th>Área</th><th>Ingreso</th><th>Contacto</th><th>Contrato hasta</th><th>Estado</th><th></th></tr></thead><tbody>${L.map(e=>`<tr><td><b>${esc(e.name)}</b></td><td>${esc(hrDept(e))}</td><td>${e.hire?dmy(e.hire):'—'}</td><td class="sm">${esc(e.phone||'—')}${e.emerg&&e.emerg.n?`<br><span class="mut">Emergencia: ${esc(e.emerg.n)} ${esc(e.emerg.p||'')}</span>`:''}</td><td>${e.cEnd?dmy(e.cEnd):'Indeterminado'}</td><td>${e.active?'<span class="tag ok">activo</span>':'<span class="tag">inactivo</span>'}</td><td class="r"><button class="btn sm" data-act="hrEmp" data-id="${e.id}">Abrir</button></td></tr>`).join('')||'<tr><td colspan="7" class="mut">Sin legajos.</td></tr>'}</tbody></table></div>
 <p class="sm mut">Los datos personales (DNI, teléfono, contacto de emergencia, domicilio, CBU) viajan cifrados a la nube. Dar de baja un legajo lo deja inactivo y conserva su historial.</p></div>`;}
function hrMonthDays(ym){const f=ym+'-01';const L=[];let k=f;while(k.slice(0,7)===ym){L.push(k);k=addDays(k,1);}return L;}
function hrCalendario(){const ym=hrCal||dkey(now()).slice(0,7);const days=hrMonthDays(ym);const E=S.employees.filter(e=>e.active);const t=dkey(now());
 const prev=addDays(ym+'-01',-1).slice(0,7),next=addDays(days[days.length-1],1).slice(0,7);
 return `<div class="card"><div class="row"><button class="btn sm" data-act="hrCalGo" data-m="${prev}" aria-label="Mes anterior">←</button><h3 style="margin:0">${esc(new Date(ym+'-15T12:00:00').toLocaleDateString('es-AR',{month:'long',year:'numeric'}))}</h3><button class="btn sm" data-act="hrCalGo" data-m="${next}" aria-label="Mes siguiente">→</button><span class="sp"></span>${can('hr')?'<button class="btn sm" data-act="hrShiftBulk">Cargar turnos de la semana</button><button class="btn gold sm" data-act="hrLeaveNew">+ Licencia</button>':''}</div>
 <div class="tw hr-cal"><table data-nosort><thead><tr><th>Persona</th>${days.map(d=>`<th class="${d===t?'hr-today':''} ${dowOfKey(d)===0||dowOfKey(d)===6?'hr-we':''}"><span class="sm">${DIAS[dowOfKey(d)].slice(0,2)}</span><br>${+d.slice(8)}</th>`).join('')}</tr></thead>
 <tbody>${E.map(e=>`<tr><th scope="row">${esc(e.name)}</th>${days.map(d=>{const lv=hrLeave(e.id,d),sh=hrShift(e.id,d);const x=sh&&d<=t?hrDay(e,d):null;
  const cls=lv?'lv lv-'+lv.type:sh?(x&&x.absent?'abs':x&&x.late?'late':'sh'):'';const txt=lv?HR_REQ_L[lv.type]:sh?sh.from.replace(':00','')+'–'+sh.to.replace(':00',''):'';
  return `<td class="hr-c ${cls}">${can('hr')?`<button data-act="hrCell" data-e="${e.id}" data-d="${d}" aria-label="${esc(e.name)} ${dmy(d)}: ${lv?HR_REQ_T[lv.type]:sh?'turno '+sh.from+' a '+sh.to:'sin turno'}">${txt||'·'}</button>`:esc(txt)}</td>`;}).join('')}</tr>`).join('')||`<tr><td class="mut">Sin legajos activos.</td></tr>`}</tbody></table></div>
 <p class="sm mut">Referencias: <span class="hr-key sh">9–17</span> turno · <span class="hr-key late">tarde</span> llegó tarde · <span class="hr-key abs">aus.</span> sin fichada · ${Object.entries(HR_REQ_L).map(([k,l])=>`<span class="hr-key lv lv-${k}">${l}</span> ${HR_REQ_T[k]}`).join(' · ')}</p></div>`;}
function hrFichaje(){const c=hrCfg();const M=[['pin','PIN de 4 dígitos (terminal compartida)','listo'],['qr','QR estático (credencial impresa) o dinámico (portal)','listo'],['nfc','Tarjeta o llavero NFC','Chrome en Android con NFC; pendiente de prueba física'],['geo','Celular con geocerca (portal del empleado)','requiere permiso de ubicación'],['face','Reconocimiento facial','pendiente de dispositivo y revisión legal (dato biométrico)'],['finger','Lector de huella','pendiente de dispositivo y revisión legal (dato biométrico)']];
 return `<div class="grid g2"><div class="card"><h3>Terminal compartida (modo kiosco)</h3><p>Pantalla completa para una tablet o PC del local: cada persona toca su nombre y pone su PIN, o pasa su QR o su llavero NFC. No hace falta correo ni cuenta individual.</p>
 <button class="btn gold" style="width:100%;min-height:56px" data-act="hrKiosk">Abrir modo kiosco</button><p class="sm mut">Para salir del kiosco se pide el PIN de salida que define el administrador en Ajustes.</p></div>
 <div class="card"><h3>Modalidades de fichaje</h3><div class="tw"><table><thead><tr><th>Modalidad</th><th>Estado</th></tr></thead><tbody>${M.map(([k,t,st])=>`<tr><td>${esc(t)}</td><td>${(k==='face'||k==='finger')?'<span class="tag warn">'+esc(st)+'</span>':c.methods[k]?'<span class="tag ok">activa</span> <span class="sm mut">'+esc(st)+'</span>':'<span class="tag">apagada</span>'}</td></tr>`).join('')}</tbody></table></div>
 <p class="sm mut">Wi-Fi local: el navegador no puede leer el nombre de la red; para validar que el celular está en el local se usa la geocerca. Se cambian en Ajustes.</p></div></div>
 <div class="card" style="margin-top:1rem"><h3>Credenciales QR y NFC</h3><div class="tw"><table><thead><tr><th>Persona</th><th>Credencial</th><th></th></tr></thead><tbody>${S.employees.filter(e=>e.active).map(e=>`<tr><td>${esc(e.name)}</td><td>${e.qk?'<span class="tag ok">emitida</span>':'<span class="tag">sin emitir</span>'}</td><td class="r">${can('staff')?`<button class="btn sm" data-act="hrCred" data-id="${e.id}">${e.qk?'Ver / reimprimir':'Emitir'}</button>${e.qk?` <button class="btn sm" data-act="hrCredNew" data-id="${e.id}">Revocar y emitir otra</button>`:''}`:''}</td></tr>`).join('')}</tbody></table></div></div>`;}
function hrRepRange(){const t=dkey(now());return{from:hrRep.from||t.slice(0,7)+'-01',to:hrRep.to||t};}
function hrRepRows(){const {from,to}=hrRepRange();return S.employees.filter(e=>e.active||S.punches.some(p=>p.empId===e.id&&dkey(p.ts)>=from&&dkey(p.ts)<=to)).map(e=>({e,st:hrStats(e,from,to)}));}
function hrReportes(){const {from,to}=hrRepRange();const R=hrRepRows();
 return `<div class="card"><div class="row"><div><label for="hr-rf">Desde</label><input type="date" id="hr-rf" value="${from}"></div><div><label for="hr-rt">Hasta</label><input type="date" id="hr-rt" value="${to}"></div><span class="sp"></span><button class="btn" data-act="hrRepCsv">Descargar CSV</button><button class="btn" data-act="hrRepPrint">Imprimir</button><button class="btn gold" data-act="hrRepSend">Enviar al contador</button></div>
 <div class="tw"><table><thead><tr><th>Persona</th><th class="r">Días trabajados</th><th class="r">Horas</th><th class="r">Horas extra</th><th class="r">Tardanzas</th><th class="r">Ausencias</th><th>Licencias (días)</th><th class="r">Fichadas incompletas</th></tr></thead><tbody>
 ${R.map(({e,st})=>`<tr><td>${esc(e.name)}</td><td class="r">${st.days}</td><td class="r">${numAR(st.h,2)}</td><td class="r">${numAR(st.ot+st.otSun,2)}</td><td class="r">${st.lateN}${st.late?' ('+st.late+' min)':''}</td><td class="r">${st.abs}</td><td>${Object.entries(st.lv).map(([k,n])=>HR_REQ_T[k]+': '+n).join(', ')||'—'}</td><td class="r">${st.flags}</td></tr>`).join('')||'<tr><td colspan="8" class="mut">Sin datos en el período.</td></tr>'}</tbody></table></div>
 <p class="sm mut">Horas = pares entrada→salida. Horas extra = lo que pasa de ${hrCfg().otDaily} h por día. Tardanza = entrada después del inicio del turno + ${hrCfg().tol} min de tolerancia. Ausencia = día con turno, sin fichada ni licencia aprobada. Es un resumen para la liquidación del contador: no es un recibo de sueldo.</p></div>`;}
function hrFlowTxt(r){return (r.flow||[]).map((st,i)=>`<span class="tag ${i<r.step?'ok':i===r.step&&r.state==='pendiente'?'warn':''}">${HR_FLOW_T[st]||st}</span>`).join(' → ')||'<span class="sm mut">directo</span>';}
function hrCanStep(r){if(r.state!=='pendiente')return false;const st=(r.flow||[])[r.step];if(isAdm())return true;if(st==='supervisor')return user&&user.role==='supervisor'&&can('hr_approve');if(st==='rrhh')return can('hr')&&can('hr_approve');return false;}
function hrSolicitudes(){if(!hrHas('approvals'))return hrLock('approvals');const L=S.hrReqs.slice().sort((a,b)=>(a.state==='pendiente'?0:1)-(b.state==='pendiente'?0:1)||b.ts-a.ts);
 return `<div class="card"><div class="row"><h3 class="sp">Solicitudes del personal</h3>${can('hr')?'<button class="btn gold sm" data-act="hrLeaveNew">+ Registrar solicitud</button>':''}</div><p class="sm mut">Circuito de aprobación: ${hrCfg().flow.map(x=>HR_FLOW_T[x]).join(' → ')} (se cambia en Ajustes). Cada paso queda con fecha y persona.</p>
 <div class="tw"><table><thead><tr><th>Persona</th><th>Tipo</th><th>Desde</th><th>Hasta</th><th class="r">Días</th><th>Circuito</th><th>Estado</th><th></th></tr></thead><tbody>${L.map(r=>`<tr><td>${esc((hrEmp(r.empId)||{name:'—'}).name)}</td><td>${HR_REQ_T[r.type]||esc(r.type)}${r.docId?` <button class="btn sm" data-act="hrFile" data-id="${r.docId}">Justificante</button>`:''}${r.note?`<br><span class="sm mut">${esc(r.note)}</span>`:''}</td><td>${dmy(r.from)}</td><td>${dmy(r.to)}</td><td class="r">${hrDays(r.from,r.to).length}</td><td>${hrFlowTxt(r)}</td><td><span class="tag ${r.state==='aprobada'?'ok':r.state==='rechazada'?'':'warn'}">${r.state}</span></td><td class="r">${hrCanStep(r)?`<button class="btn sm gold" data-act="hrReqOk" data-id="${r.id}">Aprobar</button> <button class="btn sm" data-act="hrReqNo" data-id="${r.id}">Rechazar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="mut">Sin solicitudes.</td></tr>'}</tbody></table></div></div>`;}
function hrVacaciones(){if(!hrHas('vacations'))return hrLock('vacations');const y=now()&&+dkey(now()).slice(0,4);
 return `<div class="card"><h3>Vacaciones ${y}</h3><div class="tw"><table><thead><tr><th>Persona</th><th>Ingreso</th><th class="r">Corresponden</th><th class="r">Tomadas</th><th class="r">Pedidas (pendientes)</th><th class="r">Saldo</th></tr></thead><tbody>${S.employees.filter(e=>e.active).map(e=>{const a=hrVacEntitled(e,y),t=hrVacTaken(e,y),p=hrVacTaken(e,y,1);return `<tr><td>${esc(e.name)}</td><td>${e.hire?dmy(e.hire):'<span class="tag warn">falta fecha</span>'}</td><td class="r">${a}</td><td class="r">${t}</td><td class="r">${p}</td><td class="r"><b class="${a-t<0?'negs':''}">${a-t}</b></td></tr>`;}).join('')}</tbody></table></div>
 <p class="sm mut">Días corridos según antigüedad al 31/12: ${hrCfg().vacTable.map(([a,d])=>(a?'desde '+a+' años':'menos de '+(hrCfg().vacTable[1]||[5])[0]+' años')+': '+d).join(' · ')} [VERIFICAR con el convenio y la Ley de Contrato de Trabajo]. Se pide desde el portal o se registra en «Turnos y licencias».</p></div>`;}
function hrNomina(){if(!hrHas('payroll'))return hrLock('payroll');const per=hrPer||dkey(now()).slice(0,7);const L=hrPayCalc(per);const tot=L.reduce((a,x)=>a+x.net,0);const cv=can('view_cost')||isAdm();
 const done=S.hrPays.filter(p=>p.period===per);const c=hrCfg();
 return `<div class="warnbox sm">Liquidación <b>interna</b>: no reemplaza el recibo de haberes legal ni el Libro de Sueldos Digital. Horas extra, descuentos y deducciones son parámetros del comercio [VERIFICAR con el contador y el convenio].</div>
 <div class="card"><div class="row"><div><label for="hr-per">Período</label><input type="month" id="hr-per" value="${per}"></div><span class="sp"></span><button class="btn" data-act="hrPayCsv">CSV para el contador</button><button class="btn" data-act="hrBankCsv">Archivo para el banco</button>${isAdm()?'<button class="btn gold" data-act="hrPayClose">Cerrar liquidación del período</button>':''}</div>
 <div class="tw"><table><thead><tr><th>Persona</th><th>Área</th><th class="r">Horas</th><th class="r">Extra (h)</th>${cv?'<th class="r">Básico</th><th class="r">Extras</th><th class="r">Desc. tardanza/ausencia</th><th class="r">Comisiones</th><th class="r">Bruto</th><th class="r">Deducciones</th><th class="r">Neto</th>':''}</tr></thead><tbody>
 ${L.map(x=>`<tr><td>${esc(x.name)}<br><span class="sm mut">${x.mode}</span></td><td>${esc(x.dept)}</td><td class="r">${numAR(x.hours,2)}</td><td class="r">${numAR(x.ot,2)}</td>${cv?`<td class="r">${money(x.base)}</td><td class="r">${money(x.otAmt)}</td><td class="r">${x.lateAmt+x.absAmt?'− '+money(x.lateAmt+x.absAmt):'—'}</td><td class="r">${money(x.comm)}</td><td class="r">${money(x.gross)}</td><td class="r">${x.deds.length?'− '+money(x.deds.reduce((a,d)=>a+d.a,0)):'—'}</td><td class="r"><b>${money(x.net)}</b></td>`:''}</tr>`).join('')||'<tr><td colspan="11" class="mut">Sin personal.</td></tr>'}</tbody>${cv?`<tfoot><tr><th colspan="10">Total neto</th><th class="r">${money(tot)}</th></tr></tfoot>`:''}</table></div>
 <p class="sm mut">Extras: ${c.otFactor}× (días hábiles) y ${c.otSun}× (domingos) sobre el valor hora, a partir de ${c.otDaily} h por día. Mensualizados: valor hora = sueldo ÷ ${c.monthHours} h. Tardanzas ${c.lateDisc?'se descuentan':'no se descuentan'}; ausencias ${c.absDisc?'se descuentan':'no se descuentan'}. Deducciones: ${c.deds.length?c.deds.map(d=>esc(d.n)+' '+d.pct+' %').join(', '):'ninguna cargada'}.</p>
 ${done.length?`<h4>Liquidaciones cerradas de ${per}</h4><ul>${done.map(p=>`<li>${fmtDT(p.ts)} · ${esc(p.by)} · ${p.lines.length} persona(s) · neto ${money(p.total)}${p.replaces?' · rectifica una anterior':''} <button class="btn sm" data-act="hrPayPrint" data-id="${p.id}">Recibos</button></li>`).join('')}</ul>`:''}</div>`;}
function hrDocumentos(){if(!hrHas('docsAdv'))return hrLock('docsAdv');const t=dkey(now());const D=S.hrDocs.filter(d=>!d.del).sort((a,b)=>(a.exp||'9999')<(b.exp||'9999')?-1:1);
 return `<div class="card"><div class="row"><h3 class="sp">Documentos con vencimiento</h3>${can('staff')?'<button class="btn gold sm" data-act="hrDocNew">+ Documento</button>':''}</div>
 <div class="tw"><table><thead><tr><th>Persona</th><th>Documento</th><th>Vence</th><th>Archivo</th><th>Conformidad</th></tr></thead><tbody>${D.map(d=>`<tr><td>${esc((hrEmp(d.empId)||{name:'—'}).name)}</td><td>${HR_DOC_T[d.kind]||'Documento'} · ${esc(d.name||'')}</td><td>${d.exp?`<span class="tag ${d.exp<t?'':d.exp<=addDays(t,30)?'warn':'ok'}">${dmy(d.exp)}</span>`:'—'}</td><td>${d.file?`<button class="btn sm" data-act="hrFile" data-id="${d.id}">Descargar</button>`:'—'}</td><td>${d.sig?'<span class="tag ok">firmado en pantalla '+fmtDT(d.sigTs)+'</span>':can('staff')?`<button class="btn sm" data-act="hrSign" data-k="doc" data-id="${d.id}">Firmar conformidad</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="mut">Sin documentos.</td></tr>'}</tbody></table></div>
 <p class="sm mut">La conformidad en pantalla es una constancia de recepción; <b>no</b> es firma digital con validez legal (requiere certificado y proveedor) [VERIFICAR].</p></div>
 <div class="card" style="margin-top:1rem"><div class="row"><h3 class="sp">Entrega de uniformes y herramientas</h3>${can('staff')?'<button class="btn gold sm" data-act="hrItemNew">+ Entrega</button>':''}</div>
 <div class="tw"><table><thead><tr><th>Fecha</th><th>Persona</th><th>Elemento</th><th class="r">Cant.</th><th>Talle</th><th>Recibió</th><th>Devuelto</th></tr></thead><tbody>${S.hrItems.slice().reverse().map(i=>`<tr><td>${dmy(i.date)}</td><td>${esc((hrEmp(i.empId)||{name:'—'}).name)}</td><td>${esc(i.item)}</td><td class="r">${i.qty}</td><td>${esc(i.size||'—')}</td><td>${i.sig?'<span class="tag ok">firmó</span>':`<button class="btn sm" data-act="hrSign" data-k="item" data-id="${i.id}">Firmar</button>`}</td><td>${i.ret?dmy(i.ret):can('staff')?`<button class="btn sm" data-act="hrItemRet" data-id="${i.id}">Marcar devuelto</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7" class="mut">Sin entregas.</td></tr>'}</tbody></table></div></div>`;}
function hrReclutamiento(){if(!hrHas('ats'))return hrLock('ats');const J=S.hrJobs;const job=J.find(j=>j.id===hrJob)||J.find(j=>j.state==='abierta')||J[0];
 return `<div class="card"><div class="row"><h3 class="sp">Vacantes</h3>${can('staff')?'<button class="btn gold sm" data-act="hrJobNew">+ Vacante</button>':''}</div><div class="row" role="tablist" aria-label="Vacantes">${J.map(j=>`<button class="btn sm ${job&&job.id===j.id?'on':''}" role="tab" aria-selected="${job&&job.id===j.id}" data-act="hrJobSel" data-id="${j.id}">${esc(j.title)} <span class="sm mut">(${S.hrCands.filter(c=>c.jobId===j.id&&!c.del).length})</span>${j.state==='cerrada'?' · cerrada':''}</button>`).join('')||'<p class="mut">Creá la primera vacante.</p>'}</div></div>
 ${job?`<div class="row" style="margin:.8rem 0"><b class="sp">${esc(job.title)} · ${esc(job.dept||'')}</b>${can('staff')?`<button class="btn sm" data-act="hrCandNew" data-id="${job.id}">+ Candidato</button><button class="btn sm" data-act="hrJobToggle" data-id="${job.id}">${job.state==='abierta'?'Cerrar vacante':'Reabrir'}</button>`:''}</div>
 <div class="hr-kb">${HR_STAGES.map(([k,t],i)=>{const C=S.hrCands.filter(c=>c.jobId===job.id&&c.stage===k&&!c.del);return `<section class="hr-col" aria-label="${t}"><h4>${t} <span class="tag">${C.length}</span></h4>${C.map(c=>`<article class="hr-cand"><b>${esc(c.name)}</b><span class="sm mut">${esc(c.phone||'')} ${esc(c.email||'')}</span>${c.note?`<span class="sm">${esc(c.note)}</span>`:''}<div class="row">${c.cvId?`<button class="btn sm" data-act="hrFile" data-id="${c.cvId}">CV</button>`:''}${can('staff')?`${i>0&&k!=='contratado'?`<button class="btn sm" data-act="hrCandMove" data-id="${c.id}" data-d="-1" aria-label="Volver a ${HR_STAGES[i-1][1]}">←</button>`:''}${i<3?`<button class="btn sm" data-act="hrCandMove" data-id="${c.id}" data-d="1" aria-label="Pasar a ${HR_STAGES[i+1][1]}">→</button>`:''}${k==='oferta'?`<button class="btn sm gold" data-act="hrHire" data-id="${c.id}">Contratar</button>`:''}${k!=='descartado'&&k!=='contratado'?`<button class="btn sm" data-act="hrCandDrop" data-id="${c.id}">Descartar</button>`:''}`:''}</div></article>`).join('')||'<p class="sm mut">—</p>'}</section>`;}).join('')}</div>`:''}`;}
function hrBar(rows,fmt){const mx=Math.max(1,...rows.map(r=>r[1]));return `<div class="hr-bars">${rows.map(([l,v])=>`<div class="hr-bar"><span>${esc(l)}</span><i style="width:${Math.max(2,v/mx*100)}%"></i><b>${fmt(v)}</b></div>`).join('')}</div>`;}
function hrTablero(){if(!can('hr_dash'))return '<div class="card"><p>El tablero de RR. HH. lo ve sólo el administrador o quien él habilite.</p></div>';
 const to=dkey(now()),from=addDays(to,-(hrDash-1));const E=S.employees;const act=E.filter(e=>e.active);const R=E.map(e=>({e,st:hrStats(e,from,to)}));
 const sched=R.reduce((a,x)=>a+x.st.sched,0),abs=R.reduce((a,x)=>a+x.st.abs,0),h=R.reduce((a,x)=>a+x.st.h,0),ot=R.reduce((a,x)=>a+x.st.ot+x.st.otSun,0),lateN=R.reduce((a,x)=>a+x.st.lateN,0);
 const bajas=E.filter(e=>e.leftAt&&dkey(e.leftAt)>=from).length,altas=E.filter(e=>e.hire&&e.hire>=from).length;const turn=act.length?bajas/((act.length+act.length+bajas-altas)/2||1)*100:0;
 const a=new Date(from+'T00:00:00').getTime();const sales=S.sales.filter(s=>s.status==='ok'&&s.ts>=a).reduce((x,s)=>x+s.total,0);
 const depts={};R.forEach(({e,st})=>{const c=e.payMode==='mes'?Math.round((e.salary||0)*hrDash/30):Math.round(st.h*(e.rate||0));depts[hrDept(e)]=(depts[hrDept(e)]||0)+c;});
 return `<div class="row" style="margin-bottom:.6rem"><label for="hr-dd" class="sm">Período</label><select id="hr-dd">${[7,30,90].map(n=>`<option value="${n}" ${hrDash===n?'selected':''}>Últimos ${n} días</option>`).join('')}</select><span class="sm mut">Actualizado ${fmtDT(now())}</span></div>
 <div class="grid g4">${hrKpi('Ausentismo',sched?numAR(abs/sched*100,1)+' %':'Sin datos',abs+' ausencia(s) / '+sched+' turno(s)')}${hrKpi('Rotación',numAR(turn,1)+' %',bajas+' baja(s) · '+altas+' alta(s)')}${hrKpi('Horas trabajadas',numAR(h,1),numAR(ot,1)+' h extra · '+lateN+' tardanza(s)')}${hrKpi('Ventas por hora trabajada',h?money(Math.round(sales/h)):'Sin datos','productividad del período')}</div>
 <div class="grid g2" style="margin-top:1rem"><div class="card"><h3>Costo de personal por área (estimado)</h3>${hrBar(Object.entries(depts).sort((x,y)=>y[1]-x[1]),money)}<p class="sm mut">Mensualizados: sueldo proporcional al período; por hora: horas × valor hora. Sin cargas sociales.</p></div>
 <div class="card"><h3>Ausentismo por persona</h3><div class="tw"><table><thead><tr><th>Persona</th><th class="r">Turnos</th><th class="r">Ausencias</th><th class="r">Tardanzas</th><th class="r">%</th></tr></thead><tbody>${R.filter(x=>x.st.sched).map(({e,st})=>`<tr><td>${esc(e.name)}</td><td class="r">${st.sched}</td><td class="r">${st.abs}</td><td class="r">${st.lateN}</td><td class="r">${numAR(st.abs/st.sched*100,1)}</td></tr>`).join('')||'<tr><td colspan="5" class="mut">Cargá turnos para medir ausentismo.</td></tr>'}</tbody></table></div></div></div>
 <p class="sm mut">Fórmulas: ausentismo = ausencias ÷ turnos programados sin licencia; rotación = bajas ÷ promedio de personal activo del período; productividad = ventas cobradas ÷ horas fichadas.</p>`;}
function hrAlertasTab(){const L=hrAlerts();return `<div class="card"><h3>Alertas (${L.length})</h3>${L.length?`<ul class="hr-al">${L.map(a=>`<li class="${a.c}"><span class="tag ${a.c==='red'?'':'warn'}">${esc(a.k)}</span> ${esc(a.t)} <button class="btn sm" data-act="hrTab" data-t="${a.go}">Ver</button></li>`).join('')}</ul>`:'<p class="okbox">Todo en orden.</p>'}<p class="sm mut">Se calculan solas con los datos del sistema: contratos y documentos que vencen en 30 días, ausencias y tardanzas de hoy, fichadas incompletas de la última semana, solicitudes pendientes y cambios de plan.</p></div>`;}
function hrAvisos(){return `<div class="card"><div class="row"><h3 class="sp">Avisos al personal</h3>${can('staff')?'<button class="btn gold sm" data-act="hrMsgNew">+ Aviso</button>':''}</div><p class="sm mut">El aviso queda en el sistema (cada persona lo ve en su portal). Por WhatsApp se envía <b>asistido</b>: se abre el chat con el texto listo y lo confirmás vos. El envío automático necesita WhatsApp Business API del comercio.</p>
 <div class="tw"><table><thead><tr><th>Fecha</th><th>Para</th><th>Mensaje</th><th>WhatsApp</th></tr></thead><tbody>${S.hrMsgs.slice().reverse().map(m=>{const R=hrMsgTo(m);return `<tr><td>${fmtDT(m.ts)}<br><span class="sm mut">${esc(m.by)}</span></td><td>${esc(hrMsgToTxt(m))}</td><td>${esc(m.txt)}</td><td>${R.filter(e=>e.phone).map(e=>`<a class="btn sm" target="_blank" rel="noopener noreferrer" href="https://wa.me/${esc(String(e.phone).replace(/\D/g,''))}?text=${encodeURIComponent(m.txt)}">${esc(e.name.split(' ')[0])}</a>`).join(' ')||'<span class="sm mut">sin teléfonos</span>'}</td></tr>`;}).join('')||'<tr><td colspan="4" class="mut">Sin avisos.</td></tr>'}</tbody></table></div></div>`;}
function hrMsgTo(m){return S.employees.filter(e=>e.active&&(m.to==='all'||m.to===e.id||m.to==='d:'+hrDept(e)));}
function hrMsgToTxt(m){return m.to==='all'?'Todo el personal':m.to.startsWith('d:')?'Área '+m.to.slice(2):(hrEmp(m.to)||{name:'—'}).name;}
function hrAjustes(){const c=hrCfg();const m=c.methods;const chk=(id,on,t,dis)=>`<label class="chk"><input type="checkbox" id="${id}" ${on?'checked':''} ${dis?'disabled':''}> ${t}</label>`;
 return `<div class="grid g2"><div class="card"><h3>Fichaje</h3>${chk('hc-pin',m.pin,'PIN de 4 dígitos')}${chk('hc-qr',m.qr,'QR (lector USB o cámara)')}${chk('hc-nfc',m.nfc,'Tarjeta o llavero NFC (Chrome en Android)')}${chk('hc-geo',m.geo,'Fichaje desde el celular con geocerca (portal, Plan Completo)')}
 ${chk('hc-face',false,'Reconocimiento facial — pendiente de dispositivo y revisión legal',1)}${chk('hc-fin',false,'Huella — pendiente de dispositivo y revisión legal',1)}
 <div class="grid g3"><div><label for="hc-lat">Latitud del local</label><input id="hc-lat" value="${esc(c.geo.lat)}" inputmode="decimal"></div><div><label for="hc-lon">Longitud</label><input id="hc-lon" value="${esc(c.geo.lon)}" inputmode="decimal"></div><div><label for="hc-r">Radio (m)</label><input id="hc-r" value="${c.geo.r}" inputmode="numeric"></div></div>
 <button class="btn sm" data-act="hrGeoHere" style="margin-top:.4rem">Usar la ubicación de este equipo</button>
 <label for="hc-kp">PIN para salir del modo kiosco (4 dígitos)</label><input id="hc-kp" inputmode="numeric" maxlength="4" type="password" autocomplete="off" placeholder="${c.kpin?'definido · escribí uno nuevo para cambiarlo':'sin definir'}"></div>
 <div class="card"><h3>Asistencia y liquidación interna</h3><div class="grid g2"><div><label for="hc-tol">Tolerancia de llegada (min)</label><input id="hc-tol" value="${c.tol}" inputmode="numeric"></div><div><label for="hc-otd">Horas extra desde (h por día)</label><input id="hc-otd" value="${c.otDaily}" inputmode="decimal"></div>
 <div><label for="hc-otf">Recargo días hábiles (×)</label><input id="hc-otf" value="${c.otFactor}" inputmode="decimal"></div><div><label for="hc-ots">Recargo domingos (×)</label><input id="hc-ots" value="${c.otSun}" inputmode="decimal"></div><div><label for="hc-mh">Horas del mes (mensualizados)</label><input id="hc-mh" value="${c.monthHours}" inputmode="numeric"></div></div>
 ${chk('hc-ld',c.lateDisc,'Descontar tardanzas (minutos × valor hora)')}${chk('hc-ad',c.absDisc,'Descontar ausencias sin licencia (mensualizados)')}
 <label for="hc-ded">Deducciones sobre el bruto (una por línea: nombre;porcentaje)</label><textarea id="hc-ded" rows="3" placeholder="Ejemplo;11">${esc(c.deds.map(d=>d.n+';'+d.pct).join('\n'))}</textarea><p class="sm mut">Las alícuotas legales las define el contador [VERIFICAR]; el sistema no trae ninguna cargada.</p></div>
 <div class="card"><h3>Aprobaciones y vacaciones</h3><label for="hc-fl">Circuito de aprobación</label><select id="hc-fl">${[['supervisor','rrhh','admin'],['supervisor','admin'],['rrhh','admin'],['admin']].map(f=>`<option value="${f.join(',')}" ${f.join(',')===c.flow.join(',')?'selected':''}>${f.map(x=>HR_FLOW_T[x]).join(' → ')}</option>`).join('')}</select>
 <label for="hc-vac">Vacaciones por antigüedad (años;días, una por línea)</label><textarea id="hc-vac" rows="4">${esc(c.vacTable.map(r=>r.join(';')).join('\n'))}</textarea><p class="sm mut">Cargado de ejemplo según la Ley de Contrato de Trabajo [VERIFICAR con el convenio].</p></div>
 <div class="card"><h3>Contador</h3><label for="hc-an">Nombre</label><input id="hc-an" value="${esc(c.acct.name)}" maxlength="60"><label for="hc-am">Correo</label><input id="hc-am" value="${esc(c.acct.mail)}" maxlength="80"><label for="hc-aw">WhatsApp (con código de país)</label><input id="hc-aw" value="${esc(c.acct.wa)}" inputmode="tel" maxlength="20"></div></div>
 <div class="row" style="margin-top:1rem"><button class="btn gold" data-act="hrCfgSave">Guardar ajustes</button>${IS_CLIENT?'<button class="btn" data-act="hrToggle">Apagar Recursos Humanos</button>':''}</div>`;}
const HR_VIEW={inicio:hrInicio,legajos:hrLegajos,calendario:hrCalendario,fichaje:hrFichaje,reportes:hrReportes,solicitudes:hrSolicitudes,vacaciones:hrVacaciones,nomina:hrNomina,documentos:hrDocumentos,reclutamiento:hrReclutamiento,tablero:hrTablero,alertas:hrAlertasTab,avisos:hrAvisos,ajustes:hrAjustes};
reg('rrhh','Recursos Humanos','users','hr',()=>{if(!hrOn())return `<h1>Recursos Humanos</h1><div class="card hr-off"><h2>Recursos Humanos está apagado</h2><p>Con <b>${S.employees.filter(e=>e.active).length}</b> legajo(s) activo(s) el comercio queda en el <b>${S.employees.filter(e=>e.active).length>HR_LIMIT?'Plan Completo':'Plan Micro'}</b>: fichaje en modo kiosco con PIN, QR, NFC o celular; ficha del empleado con contacto de emergencia y documentos; calendario de turnos y licencias; reporte de horas y ausencias para el contador; alertas y avisos al personal. Desde 11 legajos activos se suman solos el portal del empleado, aprobaciones, nómina, vacaciones, documentos con vencimientos y reclutamiento.</p><p class="sm mut">«Personal y fichaje» sigue funcionando igual. Activarlo no borra ni cambia datos; se puede apagar cuando quieras.</p><div class="row"><button class="btn gold" data-act="hrToggle">Activar Recursos Humanos</button><button class="btn" data-act="nav" data-id="personal">Ver Personal y fichaje</button></div></div>`;hrInit();hrPlanSync('revisión al abrir');if(!hrTabOk(hrTab))hrTab='inicio';const full=hrTier()==='full';
 return `<div class="row"><h1 class="sp">Recursos Humanos</h1><span class="tag ${full?'ok':''} hr-badge">${HR_PLAN_N[hrTier()]} · ${hrActive()} activos</span></div>
 <nav class="hr-tabs" role="tablist" aria-label="Secciones de Recursos Humanos">${HR_TABS.filter(([k])=>hrTabOk(k)).map(([k,t,f])=>`<button role="tab" class="${hrTab===k?'on':''}" aria-selected="${hrTab===k}" data-act="hrTab" data-t="${k}">${f&&HR_FULL[f]&&!full?'🔒 ':''}${t}${k==='alertas'&&hrAlerts().length?` <span class="ux-bd amber">${hrAlerts().length}</span>`:''}</button>`).join('')}</nav>${HR_VIEW[hrTab]()}`;},
 ()=>{const q=$('#hr-q');q&&q.addEventListener('input',()=>{hrQ=q.value;clearTimeout(q._t);q._t=setTimeout(()=>{rerender();const z=$('#hr-q');if(z){z.focus();z.setSelectionRange(z.value.length,z.value.length);}},250);});
  ['hr-rf','hr-rt'].forEach(id=>{const el=$('#'+id);el&&el.addEventListener('change',()=>{hrRep={from:val('hr-rf'),to:val('hr-rt')};rerender();});});
  const pe=$('#hr-per');pe&&pe.addEventListener('change',()=>{hrPer=pe.value;rerender();});const dd=$('#hr-dd');dd&&dd.addEventListener('change',()=>{hrDash=+dd.value||30;rerender();});},'Equipo');
SCREENS.rrhh.show=()=>hrOn()||isAdm(); /* V26.65: el administrador lo ve siempre (apagado muestra cómo activarlo) */
A.hrTab=el=>{hrTab=el.dataset.t;if(curScreen!=='rrhh')go('rrhh');else rerender();};
document.addEventListener('keydown',e=>{const b=e.target.closest&&e.target.closest('.hr-tabs [role=tab]');if(!b||!['ArrowRight','ArrowLeft'].includes(e.key))return;const L=[...document.querySelectorAll('.hr-tabs [role=tab]')];const i=L.indexOf(b);const n=L[(i+(e.key==='ArrowRight'?1:-1)+L.length)%L.length];n.focus();n.click();});
A.hrToggle=()=>{if(!isAdm())return toast('Sólo el administrador',1);const c=hrCfg();c.on=!c.on;hrInit();if(c.on)hrPlanSync('activación del módulo');audit('RRHH_MODULO',c.on?'activado':'apagado');save();if(!c.on&&curScreen==='rrhh')go('personal');else rerender();};
