A.hrEmp=el=>{if(!can('staff')&&!can('hr'))return;hrInit();const e=hrEmp(el.dataset.id);const ed=can('staff');const docs=e?S.hrDocs.filter(d=>d.empId===e.id&&!d.del):[];
 modal(e?'Legajo · '+e.name:'Nuevo legajo',`<div class="grid g2"><div><label for="he-n">Nombre y apellido</label><input id="he-n" value="${esc(e?e.name:'')}" maxlength="60"></div><div><label for="he-dni">DNI</label><input id="he-dni" value="${esc(e&&e.dni||'')}" inputmode="numeric" maxlength="10"></div>
 <div><label for="he-ph">Teléfono / WhatsApp</label><input id="he-ph" value="${esc(e&&e.phone||'')}" inputmode="tel" maxlength="20"></div><div><label for="he-ad">Domicilio</label><input id="he-ad" value="${esc(e&&e.addr||'')}" maxlength="100"></div>
 <div><label for="he-en">Contacto de emergencia</label><input id="he-en" value="${esc(e&&e.emerg&&e.emerg.n||'')}" maxlength="60"></div><div><label for="he-ep">Teléfono de emergencia</label><input id="he-ep" value="${esc(e&&e.emerg&&e.emerg.p||'')}" inputmode="tel" maxlength="20"></div>
 <div><label for="he-pu">Puesto</label><select id="he-pu">${S.puestos.map(p=>`<option value="${p.id}" ${e&&e.puestoId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div><label for="he-dp">Área / departamento</label><input id="he-dp" value="${esc(e&&e.dept||'')}" maxlength="40" placeholder="Ventas, Depósito, Administración…"></div>
 <div><label for="he-hi">Fecha de ingreso</label><input type="date" id="he-hi" value="${esc(e&&e.hire||'')}"></div><div><label for="he-ce">Contrato hasta (vacío = indeterminado)</label><input type="date" id="he-ce" value="${esc(e&&e.cEnd||'')}"></div>
 <div><label for="he-pm">Forma de pago</label><select id="he-pm"><option value="hora" ${!e||e.payMode!=='mes'?'selected':''}>Por hora</option><option value="mes" ${e&&e.payMode==='mes'?'selected':''}>Mensual</option></select></div><div><label for="he-r">Valor hora ($)</label>${numIn('he-r',e?e.rate:0)}</div>
 <div><label for="he-s">Sueldo mensual ($)</label>${numIn('he-s',e?e.salary:0)}</div><div><label for="he-cp">Comisión sobre sus ventas (%)</label><input id="he-cp" value="${e&&e.commPct?e.commPct:''}" inputmode="decimal" placeholder="0"></div>
 <div><label for="he-un">Usuario que vende (para comisiones)</label><select id="he-un"><option value="">—</option>${(S.users||[]).map(u=>`<option ${e&&e.userName===u.name?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div><label for="he-cbu">CBU / CVU para el pago</label><input id="he-cbu" value="${esc(e&&e.cbu||'')}" inputmode="numeric" maxlength="22"></div>
 <div><label for="he-pin">PIN de fichaje (4 dígitos)</label><input id="he-pin" inputmode="numeric" maxlength="4" autocomplete="off" value="${esc(e?e.pin:'')}"></div><div><label for="he-vx">Días de vacaciones extra</label><input id="he-vx" value="${e&&e.vacExtra?e.vacExtra:''}" inputmode="numeric" placeholder="0"></div></div>
 <label class="chk"><input type="checkbox" id="he-a" ${!e||e.active?'checked':''}> Legajo activo <span class="sm mut">(cambiar esto puede cambiar el plan: hoy ${hrActive()} activos)</span></label>
 ${e?`<h4>Documentación digitalizada</h4><ul class="sm">${docs.map(d=>`<li>${HR_DOC_T[d.kind]||'Documento'} · ${esc(d.name)}${d.exp?' · vence '+dmy(d.exp):''} ${d.file?`<button class="btn sm" data-act="hrFile" data-id="${d.id}">Descargar</button>`:''}</li>`).join('')||'<li class="mut">Sin documentos.</li>'}</ul>${ed?`<button class="btn sm" data-act="hrDocNew" data-e="${e.id}">+ Documento</button>`:''}`:''}`,
 {okText:ed?'Guardar legajo':'Cerrar',onOk:w=>{if(!ed)return;const n=val('he-n').trim();if(!n)return w._err('Falta el nombre.'),false;const pin=val('he-pin');if(!/^\d{4}$/.test(pin))return w._err('El PIN debe tener 4 dígitos.'),false;
  if(S.employees.some(x=>x.pin===pin&&x.active&&(!e||x.id!==e.id)))return w._err('Ese PIN ya lo usa otra persona activa.'),false;
  const r=cents(val('he-r')||'0'),sal=cents(val('he-s')||'0');if(isNaN(r)||r<0||isNaN(sal)||sal<0)return w._err('Revisá el valor hora y el sueldo.'),false;const cp=parseNum(val('he-cp')||'0');if(isNaN(cp)||cp<0||cp>50)return w._err('La comisión va de 0 a 50 %.'),false;
  const dni=val('he-dni').replace(/\D/g,'');if(dni&&!/^\d{7,8}$/.test(dni))return w._err('DNI inválido (7 u 8 números).'),false;const cbu=val('he-cbu').replace(/\D/g,'');if(cbu&&cbu.length!==22)return w._err('El CBU/CVU tiene 22 números.'),false;
  const hi=val('he-hi'),ce=val('he-ce');if(hi&&ce&&ce<hi)return w._err('El contrato no puede terminar antes del ingreso.'),false;const vx=parseNum(val('he-vx')||'0');if(isNaN(vx)||vx<0||vx>60)return w._err('Días extra inválidos.'),false;
  const act=$('#he-a',w).checked;const d={name:n,dni,phone:val('he-ph').trim(),addr:val('he-ad').trim(),emerg:{n:val('he-en').trim(),p:val('he-ep').trim()},puestoId:val('he-pu'),dept:val('he-dp').trim(),hire:hi,cEnd:ce,payMode:val('he-pm')==='mes'?'mes':'hora',rate:r,salary:sal,commPct:cp,userName:val('he-un'),cbu,pin,vacExtra:vx,active:act};
  const was=e?!!e.active:null;if(e){if(e.rate!==r)audit('COSTO_HORARIO',n+' '+money(e.rate)+' → '+money(r));if(e.salary!==sal)audit('SUELDO',n+' '+money(e.salary||0)+' → '+money(sal));Object.assign(e,d);}else S.employees.push(Object.assign({id:uid()},d));
  const emp=e||S.employees[S.employees.length-1];if(was===true&&!act)emp.leftAt=now();if(was===false&&act){delete emp.leftAt;}
  audit('LEGAJO',n+(e?' (editado)':' (alta)')+(was!==act?(act?' · activo':' · inactivo'):''));save();if(was!==act)hrPlanSync((act?'alta':'baja')+' de '+n);rerender();}});};
