A.hrCalGo=el=>{hrCal=el.dataset.m;rerender();};
A.hrCell=el=>{if(!can('hr'))return;const e=hrEmp(el.dataset.e),d=el.dataset.d;const sh=hrShift(e.id,d),lv=hrLeave(e.id,d);
 modal(e.name+' · '+DIAS[dowOfKey(d)]+' '+dmy(d),`${lv?`<p class="okbox">${HR_REQ_T[lv.type]} aprobada del ${dmy(lv.from)} al ${dmy(lv.to)}.</p>`:''}<h4>Turno</h4><div class="grid g2"><div><label for="hs-f">Entra</label><input type="time" id="hs-f" value="${sh?sh.from:'09:00'}"></div><div><label for="hs-t">Sale</label><input type="time" id="hs-t" value="${sh?sh.to:'17:00'}"></div></div>
 <label class="chk"><input type="checkbox" id="hs-x" ${sh?'':'checked'}> Sin turno este día</label>${!lv?`<p class="sm mut">Para una licencia de varios días usá «+ Licencia».</p>`:''}`,
 {okText:'Guardar',onOk:w=>{const off=$('#hs-x',w).checked;const f=val('hs-f'),t=val('hs-t');if(!off&&!(hrMin(f)<hrMin(t)))return w._err('La salida tiene que ser después de la entrada.'),false;
  S.hrShifts=S.hrShifts.filter(s=>!(s.empId===e.id&&s.day===d));if(!off)S.hrShifts.push({id:e.id+':'+d,empId:e.id,day:d,from:f,to:t});audit('TURNO',e.name+' '+dmy(d)+' '+(off?'sin turno':f+'–'+t));save();rerender();}});};
A.hrShiftBulk=()=>{if(!can('hr'))return;const t=dkey(now());const mon=addDays(t,-((dowOfKey(t)+6)%7));
 modal('Cargar turnos de una semana',`<label for="hb-e">Persona</label><select id="hb-e">${hrEmpOpts('',true)}</select><label for="hb-w">Semana que empieza el lunes</label><input type="date" id="hb-w" value="${mon}"><div class="grid g2"><div><label for="hb-f">Entra</label><input type="time" id="hb-f" value="09:00"></div><div><label for="hb-t">Sale</label><input type="time" id="hb-t" value="17:00"></div></div>
 <fieldset><legend>Días</legend>${[1,2,3,4,5,6,0].map(i=>`<label class="chk"><input type="checkbox" data-hbd="${i}" ${i>=1&&i<=5?'checked':''}> ${DIAS[i]}</label>`).join('')}</fieldset><p class="sm mut">Reemplaza los turnos de esos días. No toca licencias.</p>`,
 {okText:'Cargar',onOk:w=>{const f=val('hb-f'),to=val('hb-t');if(!(hrMin(f)<hrMin(to)))return w._err('La salida tiene que ser después de la entrada.'),false;const w0=val('hb-w');if(!w0)return w._err('Elegí la semana.'),false;
  const days=[...w.querySelectorAll('[data-hbd]')].filter(x=>x.checked).map(x=>+x.dataset.hbd);if(!days.length)return w._err('Elegí al menos un día.'),false;const E=val('hb-e')?[hrEmp(val('hb-e'))]:S.employees.filter(e=>e.active);let n=0;
  for(let i=0;i<7;i++){const d=addDays(w0,i);if(!days.includes(dowOfKey(d)))continue;for(const e of E){S.hrShifts=S.hrShifts.filter(s=>!(s.empId===e.id&&s.day===d));S.hrShifts.push({id:e.id+':'+d,empId:e.id,day:d,from:f,to});n++;}}
  audit('TURNOS',n+' turno(s) desde '+dmy(w0));save();toast(n+' turno(s) cargados');rerender();}});};
